const BATTLE_MODES={
scout:{id:'scout',name:'Scout',label:'Find your feet',waves:3,perWave:4,seconds:90,speed:.95,shots:1,health:0,boss:false,recharge:3,superRadius:380,bonus:30,coins:20,colour:'#8ed5b5'},
challenger:{id:'challenger',name:'Challenger',label:'The real adventure',waves:4,perWave:5,seconds:120,speed:1.18,shots:2,health:0,boss:true,bossLife:14,recharge:8,superRadius:240,bonus:60,coins:40,colour:'#d5fa59'},
expert:{id:'expert',name:'Expert',label:'For arena aces',waves:5,perWave:6,seconds:140,speed:1.4,shots:3,health:1,boss:true,bossLife:20,recharge:10,superRadius:210,bonus:100,coins:60,colour:'#f6a887'}
};
function selectedMode(){return BATTLE_MODES[profile.difficulty]||BATTLE_MODES.challenger}
function difficultyCards(){return `<section class="difficulty-section"><div class="section-title"><div><h2>Choose your challenge</h2><p>Same learning. Three ways to test your arena skills.</p></div><span class="count">YOUR PACE. YOUR PLAY.</span></div><div class="difficulty-cards">${Object.values(BATTLE_MODES).map(m=>`<button class="difficulty-card ${selectedMode().id===m.id?'selected':''}" data-difficulty="${m.id}" aria-pressed="${selectedMode().id===m.id}" style="--mode-colour:${m.colour}"><span class="difficulty-stars">${'◆'.repeat(m.shots)}</span><h3>${m.name}<span>${selectedMode().id===m.id?'✓':''}</span></h3><p>${m.label}</p><small>${m.waves} waves · ${m.seconds}s play time${m.boss?' · Boss fight':''}</small></button>`).join('')}</div></section>`}
function initialiseMatch(g){const m=selectedMode();g.mode=m;g.totalWaves=m.waves;g.totalBots=m.waves*m.perWave+(m.boss?1:0);g.time=m.seconds;g.monsterDamage+=m.id==='expert'?2:m.id==='challenger'?1:0;g.rechargeCooldown=0;g.correctChain=0;g.bestChain=0;g.questionsRight=0;g.questionsAnswered=0;g.boss=null;g.previousX=g.x;g.previousY=g.y;g.lastHurt=0;$('#arena-subtitle').textContent=m.name+' · '+g.map.name+' · Rank '+g.tier;document.querySelector('#mode-badge').textContent=m.name.toUpperCase()}
function spawnChallengeWave(){const g=game,m=g.mode;g.wave++;GameAudio.effect('wave');g.waveFlash=2;const types=m.id==='scout'?['scout','blaster','tank','scout']:['scout','blaster','tank','blaster','scout','tank'];for(let i=0;i<m.perWave;i++){const a=i*Math.PI*2/m.perWave+.38+g.wave*.16,type=types[(i+g.wave-1)%types.length],hp=(type==='tank'?3:type==='scout'?1:2)+g.monsterBonus+m.health;let pos=safeSpawn(g,a);g.enemies.push({...pos,hp,maxHp:hp,type,speed:((type==='scout'?82:type==='tank'?43:54)+g.wave*6)*(1+(g.tier-1)*.04)*m.speed,r:type==='tank'?29:23,fire:1.2+i*.25,flash:0,spawnShield:.85,dashClock:1.8+i*.31,dashTime:0,side:i%2?1:-1})}if(g.wave===g.totalWaves&&m.boss){const hp=m.bossLife*g.attackPower+g.monsterBonus,pos=safeSpawn(g,-Math.PI/2);g.boss={...pos,hp,maxHp:hp,type:'boss',speed:47*m.speed,r:38,fire:2.2,flash:0,spawnShield:1.2,phase:1,side:1};g.enemies.push(g.boss);g.floaters.push({x:g.w/2,y:180,text:'THE SCRAMBLER HAS ARRIVED',colour:'#ffd397',life:2})}g.invincible=Math.max(g.invincible,.8)}
function safeSpawn(g,angle){for(let j=0;j<20;j++){const a=angle+j*.19,x=g.w/2+Math.cos(a)*g.w*.39,y=g.h/2+Math.sin(a)*g.h*.38;if(!blocked(g,x,y,32)&&Math.hypot(x-g.x,y-g.y)>140)return{x,y}}return{x:g.w/2,y:65}}
function emitEnemyShot(g,e,angle,speed){g.enemyShots.push({x:e.x,y:e.y,dx:Math.cos(angle)*speed,dy:Math.sin(angle)*speed,life:4.2})}
function runEnemyAI(g,dt){const vx=(g.x-g.previousX)/Math.max(dt,.001),vy=(g.y-g.previousY)/Math.max(dt,.001);g.previousX=g.x;g.previousY=g.y;for(const e of g.enemies){if(e.hp<=0)continue;e.flash=Math.max(0,e.flash-dt);e.spawnShield=Math.max(0,(e.spawnShield||0)-dt);if(e.spawnShield>0)continue;const d=Math.hypot(g.x-e.x,g.y-e.y),a=Math.atan2(g.y-e.y,g.x-e.x),clear=lineClear(g,e.x,e.y,g.x,g.y,8);if(e.type==='boss'){e.phase=e.hp<e.maxHp*.5?2:1;if(d>250||!clear)steerBot(g,e,dt);else moveBody(g,e,-Math.sin(a)*e.speed*e.side*dt,Math.cos(a)*e.speed*e.side*dt,e.r);e.fire-=dt;if(e.fire<=0){GameAudio.effect('warning');if(e.phase===2){for(let i=0;i<8;i++)emitEnemyShot(g,e,g.elapsed*.35+i*Math.PI/4,155+g.tier*3)}else for(let i=-1;i<=1;i++)emitEnemyShot(g,e,a+i*.2,215+g.tier*3);e.fire=e.phase===2?1.6:2.05}}
else if(e.type==='blaster'){if(d>290||!clear)steerBot(g,e,dt);else{const retreat=d<185?-1:0;moveBody(g,e,(Math.cos(a)*retreat-Math.sin(a)*e.side*.7)*e.speed*dt,(Math.sin(a)*retreat+Math.cos(a)*e.side*.7)*e.speed*dt,23)}e.fire-=dt;if(e.fire<=0&&clear){const lead=g.mode.id==='scout'?0:Math.min(.45,d/650),aim=Math.atan2(g.y+vy*lead-e.y,g.x+vx*lead-e.x),speed=(205+g.tier*4)*(g.mode.id==='expert'?1.15:1);for(let n=0;n<g.mode.shots;n++)emitEnemyShot(g,e,aim+(n-(g.mode.shots-1)/2)*.15,speed);GameAudio.effect('enemy');e.fire=g.mode.id==='scout'?2.1:g.mode.id==='expert'?1.35:1.65}}
else{if(e.type==='scout'&&g.mode.id!=='scout'&&clear&&d<300){e.dashClock-=dt;if(e.dashClock<=0){e.dashTime=.22;e.dashClock=2.8;e.dashAngle=a}if(e.dashTime>0){e.dashTime-=dt;moveBody(g,e,Math.cos(e.dashAngle)*235*dt,Math.sin(e.dashAngle)*235*dt,23)}else steerBot(g,e,dt)}else steerBot(g,e,dt)}
if(g.mode.id!=='scout'&&e.type==='blaster'){const shot=g.bullets.find(b=>Math.hypot(b.x-e.x,b.y-e.y)<105);if(shot){const n=Math.hypot(shot.dx,shot.dy)||1;moveBody(g,e,-shot.dy/n*e.side*75*dt,shot.dx/n*e.side*75*dt,23)}}if(d<e.r+26){damagePlayer(g);moveBody(g,e,-Math.cos(a)*40*dt,-Math.sin(a)*40*dt,e.r)}}}
function renderBoss(c,e,g){c.save();c.translate(e.x,e.y);const pulse=e.fire<.65?Math.sin(g.elapsed*18)*.12+.9:1;c.globalAlpha=e.spawnShield>0?.55:1;ellipse(c,3,41,48,17,'#2c304855');c.strokeStyle=e.phase===2?'#ffab8c':'#b5a0ef';c.lineWidth=3;c.beginPath();c.arc(0,0,53+(1-pulse)*20,0,7);c.stroke();roundRect(c,-37,-37,74,77,20,e.flash?'#fff1c7':e.phase===2?'#b76c7b':'#7664a2','#37314e');roundRect(c,-28,-19,56,32,10,'#2c2b46');ellipse(c,-13,-3,6,8,'#ffce9b');ellipse(c,13,-3,6,8,'#ffce9b');roundRect(c,-49,-6,14,39,6,'#494160','#a58bbf');roundRect(c,35,-6,14,39,6,'#494160','#a58bbf');c.fillStyle='#d5fa59';c.beginPath();c.moveTo(0,15);c.lineTo(12,27);c.lineTo(0,38);c.lineTo(-12,27);c.closePath();c.fill();c.strokeStyle='#ead7af';c.beginPath();c.moveTo(-18,-37);c.lineTo(-26,-54);c.moveTo(18,-37);c.lineTo(26,-54);c.stroke();ellipse(c,-27,-55,6,6,'#efb48e');ellipse(c,27,-55,6,6,'#efb48e');c.restore()}
function updateProHUD(g){const life=document.querySelector('#life-fill');if(life)life.style.width=Math.max(0,g.hp/g.maxHp*100)+'%';const energy=document.querySelector('#energy-pips');if(energy&&(g.hudAmmo!==g.ammo||g.hudMaxAmmo!==g.maxAmmo)){g.hudAmmo=g.ammo;g.hudMaxAmmo=g.maxAmmo;energy.innerHTML=Array.from({length:g.maxAmmo},(_,i)=>`<i class="${i<g.ammo?'filled':''}"></i>`).join('')}const cooldown=Math.ceil(g.rechargeCooldown);const recharge=document.querySelector('.recharge-button');if(recharge){recharge.classList.toggle('cooling',cooldown>0);recharge.setAttribute('aria-label',cooldown>0?'Reload ready in '+cooldown+' seconds':'Reload energy. Keyboard: Q.')}const qLabel=document.querySelector('#recharge-label');if(qLabel)qLabel.textContent=cooldown>0?'ϟ '+cooldown+'s':'ϟ Reload';const timer=document.querySelector('#timer');timer?.classList.toggle('urgent',g.time<=20);const boss=document.querySelector('#boss-hud');if(boss){boss.hidden=!g.boss||g.boss.hp<=0;if(!boss.hidden){document.querySelector('#boss-life').style.width=Math.max(0,g.boss.hp/g.boss.maxHp*100)+'%';document.querySelector('#boss-phase').textContent=g.boss.phase===2?'OVERDRIVE':'GUARDIAN';document.querySelector('#boss-number').textContent=Math.max(0,g.boss.hp)+' / '+g.boss.maxHp}}}
function showMatchResults(win){const g=game;if(!g)return;GameAudio.effect(win?'win':'finish');const score=g.kills*30+g.questionsRight*40+(win?200+Math.ceil(g.time)*2:0),key=g.mode.id+':'+g.tier;profile.personalBests??={};const old=profile.personalBests[key]||0,newBest=score>old;if(newBest)profile.personalBests[key]=score;profile.matches++;if(win){profile.wins++;profile.xp+=g.mode.bonus;profile.coins+=g.mode.coins}save();game=null;quiz=null;cancelAnimationFrame(raf);openModal(`${topModal(g.mode.name.toUpperCase()+' · MATCH COMPLETE')}<div class="results pro-results"><div class="result-emblem">${win?'✦':'⚑'}</div><span class="result-kicker">${newBest?'NEW PERSONAL BEST':'RANK '+g.tier+' · '+g.mode.name.toUpperCase()}</span><h2 id="modal-title">${win?'Arena conquered.':'Next time, stronger.'}</h2><p>${win?'You kept moving, used your knowledge and beat the arena.':g.hp<=0?'Use cover to break enemy aim. Dash sideways when a blaster charges.':'Try collecting energy between fights and saving your super for a cluster.'}</p><div class="match-score">${score}<small>MATCH SCORE</small></div><div class="results-grid"><div><b>${g.kills}/${g.totalBots}</b><span>BOTS DEFEATED</span></div><div><b>${g.questionsAnswered?Math.round(g.questionsRight/g.questionsAnswered*100):0}%</b><span>QUESTION ACCURACY</span></div><div><b>${g.bestChain}</b><span>BEST ANSWER STREAK</span></div><div><b>${win?'+'+g.mode.bonus:g.wave+'/'+g.totalWaves}</b><span>${win?'BONUS XP':'WAVES REACHED'}</span></div></div><div class="modal-actions" style="justify-content:center"><button class="primary" data-rematch="${g.subject}">Play again →</button><button class="secondary" data-action="done">Change challenge</button></div><p class="notice" style="margin-top:18px">Personal best: ${Math.max(old,score)} · ${g.mode.name} · Rank ${g.tier}<br>Time for a stretch or water break?</p></div>`)}
